-- 试卷生成功能迁移脚本（MySQL 8+）
-- application.yml 使用 ddl-auto=update 时实体会自动建表；生产环境可单独执行本脚本。
CREATE TABLE IF NOT EXISTS question_bank (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,subject_id BIGINT,visibility VARCHAR(30) NOT NULL DEFAULT 'public',owner_id BIGINT,description TEXT,bank_type VARCHAR(40),create_time DATETIME,update_time DATETIME,INDEX idx_question_bank_visibility(visibility),INDEX idx_question_bank_owner(owner_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS question (id BIGINT AUTO_INCREMENT PRIMARY KEY,bank_id BIGINT NOT NULL,subject_id BIGINT,subject VARCHAR(80),chapter VARCHAR(80),knowledge_point VARCHAR(120),question_type VARCHAR(30) NOT NULL,difficulty VARCHAR(20),content TEXT NOT NULL,options TEXT,answer TEXT,analysis TEXT,creator_id BIGINT,create_time DATETIME,update_time DATETIME,INDEX idx_question_bank(bank_id),INDEX idx_question_filter(subject,question_type,difficulty)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS question_bank_item (id BIGINT AUTO_INCREMENT PRIMARY KEY,bank_id BIGINT NOT NULL,question_id BIGINT NOT NULL,added_by BIGINT NOT NULL,create_time DATETIME,UNIQUE KEY uk_question_bank_item(bank_id,question_id),INDEX idx_question_bank_item_bank(bank_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS question_favorite (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,question_id BIGINT NOT NULL,create_time DATETIME,UNIQUE KEY uk_question_favorite(user_id,question_id),INDEX idx_question_favorite_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS paper (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,subject_id BIGINT,subject VARCHAR(100),category VARCHAR(40) NOT NULL,remark TEXT,duration INT,total_score INT DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'draft',creator_id BIGINT NOT NULL,create_time DATETIME,update_time DATETIME,INDEX idx_paper_creator(creator_id,update_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS paper_question (id BIGINT AUTO_INCREMENT PRIMARY KEY,paper_id BIGINT NOT NULL,question_id BIGINT NOT NULL,question_order INT NOT NULL,score INT NOT NULL DEFAULT 5,source_type VARCHAR(30),source_id BIGINT,create_time DATETIME,UNIQUE KEY uk_paper_question(paper_id,question_id),UNIQUE KEY uk_paper_question_order(paper_id,question_order),INDEX idx_paper_question_paper(paper_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
